impl std::error::Error for ValidationException {}

impl SerializableStruct for ValidationException {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&VALIDATION_EXCEPTION_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of the body this service puts a failure in.
///
/// Every error shape in the IVS RealTime model names its detail member
/// `exceptionMessage` and carries no `@jsonName` (`smithy_query(query="shape",
/// shape="ValidationException,ResourceNotFoundException")`), so serializing one of those
/// shapes renders `{"exceptionMessage": …}` — a key no SDK error parser reads. An SDK
/// takes the error message from the body's `message` / `Message` key and reports nothing
/// when neither is there, and the recorded IVS RealTime responses arrive with a populated
/// message, so the body AWS really sends carries `message`. This member is that key.
///
/// It is a BODY rendering only: the error code and the HTTP status still come from the
/// modelled error shape the operation declares — see [`Scaffolded::stated`].
static STATED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#StatedError$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message")
.with_json_name("message");

/// Schema for the one-member body [`STATED_MESSAGE`] describes.
///
/// In the `smithy.framework` namespace for the same reason as [`NOT_IMPLEMENTED_SCHEMA`]:
/// it is not a shape in any model, so it must not collide with a modelled one. Nothing
/// about the error's identity travels here — the wire code comes from
/// [`OperationError::shape_name`] on the modelled error and the status from
/// [`OperationError::http_status`].
pub static STATED_ERROR_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#StatedError",
        "smithy.framework",
        "StatedError",
    ),
    ShapeType::Structure,
    &[&STATED_MESSAGE],
);

/// Just the body [`STATED_MESSAGE`] describes, for a failure this service states OUTSIDE
/// the modelled-error channel.
///
/// The one case is the constraint refusal `crate::service`'s per-operation wrapper answers
/// before any handler runs: it has a sentence to state and no modelled error VALUE to
/// carry it, since the refusal belongs to the request rather than to an operation's error
/// enum. The wire code and status travel beside it, as the arguments of
/// `ServerHttpProtocol::serialize_error`.
#[derive(Debug, Clone)]
pub struct StatedBody {
    /// The text the body's `message` key carries.
    pub message: String,
}

impl StatedBody {
    /// A body stating `message`.
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

impl SerializableStruct for StatedBody {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&STATED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// A modelled failure plus the text this service states it with.
///
/// `modeled` is the operation's own modelled error — the one `#[operation_error]` accepts
/// only because the model declares it for this operation — and it alone decides the wire
/// error code and the HTTP status. `message` is what the body's `message` key carries.
#[derive(Debug, Clone)]
pub struct Stated<E> {
    /// The modelled error this failure is, which names the code and the status.
    pub modeled: E,
    /// The text the body states, built by `crate::state`'s message rules.
    pub message: String,
}

impl<E: std::fmt::Display> std::fmt::Display for Stated<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.modeled, self.message)
    }
}

impl<E: std::error::Error + 'static> std::error::Error for Stated<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.modeled.source()
    }
}

impl<E> SerializableStruct for Stated<E> {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&STATED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// A failure whose wire error CODE this service's model does not declare for the
/// operation answering it, carried explicitly because no modelled shape names it.
///
/// Reach for it only where a recording shows AWS answering a code that is not in the
/// operation's modelled error set — IVS RealTime's tagging surface answers
/// `NotFoundException` and `BadRequestException` where the rest of the service answers
/// `ResourceNotFoundException` and `ValidationException`
/// (`crate::state::TAGGING_NOT_FOUND_CODE`, `crate::state::TAGGING_BAD_REQUEST_CODE`).
/// Everything the model does declare goes through [`Scaffolded::stated`], where the code
/// and status stay model-derived.
#[derive(Debug, Clone)]
pub struct Unmodeled {
    /// The wire error code (`__type` / `x-amzn-errortype`).
    code: &'static str,
    /// The HTTP status the recorded response carries.
    status: u16,
    /// The text the body's `message` key carries.
    message: String,
}

impl Unmodeled {
    /// A failure answered with `code` and `status`, stating `message`.
    pub fn new(code: &'static str, status: u16, message: impl Into<String>) -> Self {
        Self {
            code,
            status,
            message: message.into(),
        }
    }
}

impl std::fmt::Display for Unmodeled {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for Unmodeled {}

impl SerializableStruct for Unmodeled {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&STATED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    ///
    /// Its BODY is the modelled shape's own members, which for this service means the
    /// `exceptionMessage` key no SDK error parser reads — so an implemented handler
    /// states a modelled failure through [`Scaffolded::stated`] instead, keeping this
    /// variant for the generated `From` impl each operation carries.
    Modeled(E),
    /// A modeled error the operation declares, with the body AWS sends for it: the
    /// `message` key. See [`Stated`] and [`Scaffolded::stated`].
    Stated(Stated<E>),
    /// A failure answered with an error code the operation's model does not declare.
    /// See [`Unmodeled`].
    Unmodeled(Unmodeled),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// State `modeled` the way this service states it on the wire: the modelled shape's
    /// own error code and HTTP status, with `message` under the body key AWS sends
    /// (`message`, not the model's `exceptionMessage`; see [`STATED_MESSAGE`]).
    ///
    /// This is how an implemented handler returns a modelled failure. `modeled` is the
    /// operation's own error enum, so the compiler still refuses a failure this operation
    /// does not model, and the text comes from the message rules in `crate::state`.
    pub fn stated(modeled: E, message: impl Into<String>) -> Self {
        Self::Stated(Stated {
            modeled,
            message: message.into(),
        })
    }

    /// Answer with an error code the operation's model does not declare. See
    /// [`Unmodeled`] for the one surface of this service that needs it.
    pub fn unmodeled(code: &'static str, status: u16, message: impl Into<String>) -> Self {
        Self::Unmodeled(Unmodeled::new(code, status, message))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::Stated(e) => write!(f, "{e}"),
            Self::Unmodeled(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::Stated(e) => e.source(),
            Self::Unmodeled(e) => e.source(),
            Self::ValidationException(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            // The stated body: the `message` key, not the modelled shape's members.
            Self::Stated(e) => e,
            Self::Unmodeled(e) => e,
            Self::ValidationException(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::Stated(_) | Self::Unmodeled(_) => &STATED_ERROR_SCHEMA,
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            // The code stays MODEL-derived: it is the modelled shape the operation
            // declares, read off the same enum `Modeled` carries.
            Self::Stated(e) => e.modeled.shape_name(),
            Self::Unmodeled(e) => e.code,
            Self::ValidationException(_) => "ValidationException",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            // The status stays MODEL-derived (`@httpError` on the modelled shape).
            Self::Stated(e) => e.modeled.http_status(),
            Self::Unmodeled(e) => e.status,
            Self::ValidationException(_) => 400,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            Self::Stated(e) => e.modeled.query_error_code(),
            // Same reason: the synthetic shape carries no `awsQueryError` trait.
            Self::Unmodeled(_) => None,
            // Same reason: the synthetic shape carries no `awsQueryError` trait.
            Self::ValidationException(_) => None,
        }
    }
}
